INSERT IGNORE INTO `content_sections` (`section_key`, `data`) VALUES
('hero', '{"title":"Ensemble, nous vous ouvrons le monde.","text":"Derrière chaque demande de visa, il y a un rêve : étudier, travailler, bâtir une nouvelle vie ailleurs. Nous portons le vôtre avec rigueur et bienveillance.","image":null}');
INSERT IGNORE INTO `content_sections` (`section_key`, `data`) VALUES
